from pathlib import Path
import base64

FILES = {'apps/dashboard/user_profile_v67.py': '', 'patch_user_profile_v67.py': '', 'templates/dashboard/user_profile.html': '', 'static/css/user_profile_v67.css': ''}

for filename, encoded in FILES.items():
    path = Path(filename)
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    if path.exists():
        backup = path.with_name(
            path.name
            + ".before_user_profile_v67.bak"
        )

        if not backup.exists():
            backup.write_text(
                path.read_text(
                    encoding="utf-8"
                ),
                encoding="utf-8",
            )

    path.write_bytes(
        base64.b64decode(
            encoded
        )
    )

    print(
        "OK:",
        filename,
    )

print("")
print("V67 instalada.")
print("Ahora ejecute: python patch_user_profile_v67.py")
